def strip_md_table(line):
    return line.strip().strip('|')

def parse_md(path):
    txt = open(path, encoding='utf-8').read()
    rec = {'file': os.path.basename(path)}
    for line in txt.splitlines():
        m = re.match(r'^\|\s*([^|]+?)\s*\|\s*(.+?)\s*\|\s*$', line)
        if m and m.group(1).strip() in ('Matter','Portfolio key','Evidence role','Immutable entity',
                                        'Referenced revision','Current revision','Custodian','Reviewer'):
            rec[m.group(1).strip()] = m.group(2).strip()
    # title
    m = re.match(r'^# (.+)$', txt, re.M)
    if m: rec['title'] = m.group(1)
    # native record section
    m = re.search(r'## Native record\s*\n\s*\n(.+?)\n\s*\n## ', txt, re.S)
    if m: rec['native_record'] = ' '.join(m.group(1).split())
    return rec

def parse_txt(path):
    txt = open(path, encoding='utf-8').read()
    rec = {'file': os.path.basename(path)}
    for line in txt.splitlines():
        m = re.match(r'^([A-Za-z ]+):\s*(.+)$', line)
        if m and m.group(1).strip() in ('Matter','Portfolio key','Evidence role','Immutable entity',
                                        'Referenced revision','Current revision','Custodian','Reviewer','Record'):
            rec[m.group(1).strip()] = m.group(2).strip()
    m = re.match(r'^# (.+)$', txt, re.M)
    if m: rec['title'] = m.group(1)
    m = re.search(r'Native record\s*\n\s*\n(.+?)\n\s*\n', txt, re.S)
    if m: rec['native_record'] = ' '.join(m.group(1).split())
    return rec

def parse_eml(path):
    msg = BytesParser(policy=policy.default).parse(open(path,'rb'))
    body = msg.get_body(preferencelist=('plain',))
    text = body.get_content() if body else ''
    rec = {'file': os.path.basename(path)}
    for line in text.splitlines():
        m = re.match(r'^([A-Za-z ]+):\s*(.+)$', line)
        if m and m.group(1).strip() in ('Matter','Portfolio key','Evidence role','Immutable entity',
                                        'Referenced revision','Current revision','Custodian','Reviewer','Record'):
            rec[m.group(1).strip()] = m.group(2).strip()
    m = re.search(r'Native record\s*\n\s*\n(.+?)\n\s*\n', text, re.S)
    if m: rec['native_record'] = ' '.join(m.group(1).split())
    else:
        # eml: body may be embedded after a blank line
        parts = text.split('\n\n', 2)
        if len(parts) >= 3: rec['native_record'] = ' '.join(parts[1].split())
    return rec

def parse_csv(path):
    rows = list(csv.DictReader(open(path, encoding='utf-8')))
    rec = {'file': os.path.basename(path)}
    meta = rows[0]
    for k,v in meta.items():
        if k and v: rec[k.strip()] = v.strip()
    return rec

def parse_json(path):
    d = json.load(open(path, encoding='utf-8'))
    d['file'] = os.path.basename(path)
    return d

def parse_xml(path):
    t = ET.parse(path)
    r = t.getroot()
    rec = {'file': os.path.basename(path)}
    def walk(e):
        for c in e:
            tag = c.tag.split('}')[-1]
            if len(c) == 0 and c.text and c.text.strip():
                rec[tag] = c.text.strip()
            else:
                walk(c)
    walk(r)
    return rec

TAG_RE = re.compile(r'<[^>]+>')
def parse_html(path):
    raw = open(path, encoding='utf-8').read()
    rec = {'file': os.path.basename(path)}
    m = re.search(r'<h1>(.*?)</h1>', raw)
    if m: rec['title'] = TAG_RE.sub('', m.group(1))
    for m in re.finditer(r'<dt>(.*?)</dt><dd>(.*?)</dd>', raw):
        k = TAG_RE.sub('', m.group(1)).strip()
        v = htmllib.unescape(TAG_RE.sub('', m.group(2))).strip()
        if k in ('Matter','Portfolio key','Evidence role','Immutable entity','Referenced revision',
                 'Current revision','Custodian','Reviewer','Record'):
            rec[k] = v
    m = re.search(r'<h2>Native record</h2><p>(.*?)</p>', raw, re.S)
    if m: rec['native_record'] = ' '.join(htmllib.unescape(TAG_RE.sub('', m.group(1))).split())
    return rec

def parse_pdf(path):
    raw = open(path,'rb').read().decode('latin-1')
    texts = re.findall(r'\((.*?)\)\s*Tj', raw)
    joined = ' '.join(t.replace('\\(','(').replace('\\)',')') for t in texts)
