        if m: rec[m.group(1)] = m.group(2).strip()
    m = re.search(r'Native record\s+(.+?)(?:Reliance limits|Native rows)', joined)
    if m: rec['native_record'] = ' '.join(m.group(1).split())
    return rec

PARSERS = {'.md':parse_md,'.txt':parse_txt,'.eml':parse_eml,'.csv':parse_csv,
           '.json':parse_json,'.xml':parse_xml,'.html':parse_html,'.pdf':parse_pdf}

records = []
for dirpath, dirs, files in os.walk(ROOT):
