              'correspondence':'correspondence','chronology and custody':'chronology_and_custody',
              'independent counterrecord':'independent_counterrecord'}

def canon_role(text):
    for k,v in ROLE_CANON.items():
        if re.search(k.replace(' ', r'[ _]'), text, re.I): return v
    return None

# native-record extraction
def native_record(text):
    m = re.search(r'NATIVE RECORD\s*\n+(.+?)\n\s*\n', text, re.S)
    if m: return ' '.join(m.group(1).split())
    m = re.search(r'"heading":\s*"Native record",\s*\n\s*"text":\s*"(.+?)"', text, re.S)
